package cn.naiblog.carsearch.controller;
import cn.naiblog.carsearch.wechat.WechatMessageCryptoService;import cn.naiblog.carsearch.wechat.WechatRefundEventService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController public class WechatMessageController{private final WechatMessageCryptoService crypto;private final WechatRefundEventService events;public WechatMessageController(WechatMessageCryptoService c,WechatRefundEventService e){crypto=c;events=e;}
@GetMapping("/wechat/message")public ResponseEntity<String>verify(@RequestParam(defaultValue="")String signature,@RequestParam(name="msg_signature",defaultValue="")String msg,@RequestParam String timestamp,@RequestParam String nonce,@RequestParam String echostr){try{return ResponseEntity.ok().contentType(MediaType.TEXT_PLAIN).body(msg.isBlank()?(crypto.verify(signature,timestamp,nonce)?echostr:"forbidden"):crypto.echo(echostr,msg,timestamp,nonce));}catch(Exception e){return ResponseEntity.status(503).body("service unavailable");}}
@PostMapping("/wechat/message")public ResponseEntity<?>receive(HttpServletRequest req,@RequestParam(name="encrypt_type",defaultValue="")String type,@RequestParam String timestamp,@RequestParam String nonce,@RequestParam(name="msg_signature")String sig,@RequestBody String body){try{if(!"aes".equalsIgnoreCase(type)||body.length()>131072)return ResponseEntity.badRequest().body("secure mode required");Map<String,Object>event=crypto.envelope(body,sig,timestamp,nonce);return ResponseEntity.ok(crypto.response(events.handle(event)));}catch(Exception e){try{return ResponseEntity.ok(crypto.response(Map.of("ErrCode",1,"ErrMsg","processing failed")));}catch(Exception ignored){return ResponseEntity.status(503).body("service unavailable");}}}}
